<script setup lang="ts">
import {editorLink} from '~/shared/cms/workflow.mjs'
definePageMeta({layout:'admin'})
const {api,session,message}=useCmsAdmin()
const {data:sections,error}=await useCmsWorkspaces()
const drafts=computed(()=>(sections.value||[]).filter(s=>s.pending)),recent=computed(()=>(sections.value||[]).toSorted((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,6))
const {data:inbox,error:inboxError}=await useAsyncData<any[]>('cms-inbox-count',()=>session.value?.role==='admin'?api('inbox'):Promise.resolve([]))
</script>
<template><div class="cms-page"><div class="cms-heading"><div><h1>今天要修改什麼？</h1><p class="cms-muted">{{ session?.name }}，從官網位置或日常工作開始。</p></div><a href="/" target="_blank" rel="noopener noreferrer" class="cms-button">查看官網 ↗</a></div><p v-if="inboxError" class="cms-error" role="alert">{{ message(inboxError) }}</p><div class="cms-task-grid"><NuxtLink to="/admin/home" class="cms-panel cms-task-card"><span>01</span><strong>修改首頁</strong><small>輪播、品牌系列、案例與門市</small></NuxtLink><NuxtLink to="/admin/content?section=news" class="cms-panel cms-task-card"><span>02</span><strong>修改優惠消息</strong><small>最新消息、優惠活動與媒體影音</small></NuxtLink><NuxtLink to="/admin/content?section=all" class="cms-panel cms-task-card"><span>03</span><strong>全部可修改頁面</strong><small>依官網名稱尋找修改位置</small></NuxtLink><NuxtLink to="/admin/media" class="cms-panel cms-task-card"><span>04</span><strong>上傳圖片或型錄</strong><small>管理圖片、檔案與使用位置</small></NuxtLink></div><div class="cms-metrics"><NuxtLink to="/admin/content" class="cms-metric"><div>可修改的位置<strong>{{ sections?.length||0 }}</strong></div></NuxtLink><a href="#cms-pending" class="cms-metric"><div>尚未更新到官網<strong>{{ drafts.length }}</strong></div></a><NuxtLink v-if="session?.role==='admin'" to="/admin/inbox" class="cms-metric"><div>待處理申請<strong>{{ inbox?.filter(i=>i.status==='待處理').length||0 }}</strong></div></NuxtLink></div><div class="cms-overview-bottom"><section id="cms-pending" class="cms-panel"><div class="cms-section-heading"><h2>繼續確認修改</h2></div><NuxtLink v-for="s in drafts" :key="s.id" :to="editorLink(s.id)" class="cms-resource-row"><strong>{{ s.title }}</strong><span>查看修改 →</span></NuxtLink><p v-if="!drafts.length" class="cms-empty">目前沒有待確認的修改</p></section><section class="cms-panel"><div class="cms-section-heading"><h2>最近修改</h2></div><NuxtLink v-for="s in recent" :key="s.id" :to="editorLink(s.id)" class="cms-resource-row"><strong>{{ s.title }}</strong><time>{{ new Date(s.updatedAt).toLocaleDateString('zh-TW') }}</time></NuxtLink></section></div></div></template>
